// Chatwoot envia el texto en body.content
const textoOriginal = ($json.body?.content || '').trim();
const texto = textoOriginal.toLowerCase();
// Version sin acentos para comparar palabras clave
const t = texto.normalize('NFD').replace(/[̀-ͯ]/g, '');

const telefonoRaw = $json.body?.conversation?.meta?.sender?.phone_number || '';
const telefono = telefonoRaw.replace('+', '');

let intent = 'desconocido';
let codigo = null;
let lluvia = null;          // { mm, fecha, lote } cuando se registra lluvia
let satelite_tipo = null;   // parcela | nubes | ndvi
let lluvia_error = null;

// =====================================================
// DETECTAR REGISTRO IAGRO
// Formato esperado:
// [IAGRO]:[BZuABk2]
// =====================================================
const registroMatch = textoOriginal.match(/^\s*\[IAGRO\]\s*:\s*\[([A-Za-z0-9_-]+)\]/i);

if (registroMatch) {
  intent = 'registro';
  codigo = registroMatch[1];
}

// =====================================================
// REGISTRO RAPIDO DE LLUVIA
// Ej: "llovio 15 mm", "cayeron 8,5 milimetros ayer en el lote norte", "lluvia 12mm 05/10"
// =====================================================
if (intent === 'desconocido' && /(llov|lluvi|cayo|cayeron|registr|anot|pluvio)/.test(t)) {
  // Fecha explicita dd/mm o dd/mm/aaaa (se quita del texto para no confundirla con los mm)
  let fecha = $now.toISODate();
  let resto = t;
  const fm = t.match(/\b(\d{1,2})[\/-](\d{1,2})(?:[\/-](\d{2,4}))?\b/);
  if (fm) {
    const anio = fm[3] ? (fm[3].length === 2 ? 2000 + Number(fm[3]) : Number(fm[3])) : $now.year;
    const f = DateTime.fromObject({ year: anio, month: Number(fm[2]), day: Number(fm[1]) });
    if (f.isValid) fecha = f.toISODate();
    resto = t.replace(fm[0], ' ');
  } else if (/antier|anteayer/.test(t)) {
    fecha = $now.minus({ days: 2 }).toISODate();
  } else if (/\bayer\b|anoche/.test(t)) {
    fecha = $now.minus({ days: 1 }).toISODate();
  }

  const conUnidad = resto.match(/(\d+(?:[.,]\d+)?)\s*(mm|milimetros?|ml)\b/);
  const soloNumero = /(llovio|llovieron|cayo|cayeron)/.test(resto) ? resto.match(/\b(\d+(?:[.,]\d+)?)\b/) : null;
  const m = conUnidad || soloNumero;

  if (m) {
    const mm = Math.round(parseFloat(m[1].replace(',', '.')) * 10) / 10;
    const loteMatch = textoOriginal.match(/en\s+(?:el\s+|la\s+)?(lote|parcela|potrero|chacra|campo|sector)\s+([\wáéíóúñÁÉÍÓÚÑ-]{1,30})/i);
    const lote = loteMatch
      ? `${loteMatch[1].charAt(0).toUpperCase()}${loteMatch[1].slice(1).toLowerCase()} ${loteMatch[2]}`
      : 'Lote principal';

    if (fecha > $now.toISODate()) {
      intent = 'lluvia_ayuda';
      lluvia_error = 'La fecha no puede ser futura.';
    } else if (mm < 0 || mm > 500) {
      intent = 'lluvia_ayuda';
      lluvia_error = 'La cantidad debe estar entre 0 y 500 mm.';
    } else {
      intent = 'lluvia_registro';
      lluvia = { mm, fecha, lote };
    }
  }
}

// =====================================================
// INTENCIONES NORMALES
// El orden importa: la primera que coincide gana.
// (agregar nuevas palabras clave aqui = escala sin tocar el resto del flujo)
// Las palabras van SIN acentos porque se comparan contra el texto normalizado.
// =====================================================
if (intent === 'desconocido') {
  const intents = {
    lluvia_historial: ['historial', 'mis lluvias', 'cuanto llovio', 'acumulado', 'mis registros', 'cuaderno'],
    lluvia_ayuda: ['registrar lluvia', 'anotar lluvia', 'pluviometro', 'registrar'],
    alertas: ['alerta', 'helada', 'granizo', 'tormenta', 'riesgo', 'peligro'],
    fumigar: ['fumig', 'pulveriz', 'asperj', 'aplicar'],
    riego: ['riego', 'regar', 'evapotrans'],
    satelite: ['satel', 'imagen', 'ndvi', 'nubes', 'vegetacion', 'salud del cultivo', 'mi parcela', 'foto'],
    planes: ['planes', 'plan pro', 'precio', 'premium', 'suscrib', 'pagar', 'costo', 'cuanto cuesta'],
    pronostico: ['pronostico', 'clima', 'lluvia', 'tiempo', 'llover', 'llueve'],
    radar: ['radar'],
    saludo: ['hola', 'buenas', 'buenos dias', 'buen dia'],
    ayuda: ['ayuda', 'menu', 'opciones'],
    saludo_final: ['gracias', 'ok', 'perfecto', 'listo', 'entendido', 'hasta luego', 'adios', 'chau', 'nos vemos']
  };

  for (const [nombre, palabras] of Object.entries(intents)) {
    if (palabras.some(p => t.includes(p))) {
      intent = nombre;
      break;
    }
  }
}

if (intent === 'satelite') {
  satelite_tipo = /ndvi|vegetacion|salud/.test(t) ? 'ndvi' : /nube/.test(t) ? 'nubes' : 'parcela';
}

// Intenciones que requieren usuario registrado (pasan por un solo IF)
const SERVICIOS = ['lluvia_registro', 'lluvia_historial', 'alertas', 'fumigar', 'riego', 'satelite'];

return [{
  json: {
    ...$json,
    intent,
    es_servicio: SERVICIOS.includes(intent) ? 'si' : 'no',
    texto_original: textoOriginal,
    texto,
    codigo,
    lluvia,
    lluvia_error,
    satelite_tipo,
    conversation_id: $json.body?.conversation?.id,
    account_id: $json.body?.account?.id,
    contact_name: $json.body?.conversation?.meta?.sender?.name || 'Cliente',
    telefono
  }
}];

// Postgres reemplaza $json con las columnas de la tabla (o vacio si no hay match).
// Aqui lo recuperamos y lo adjuntamos como un solo objeto "usuario", conservando
// todos los datos del mensaje original (intent, telefono, codigo, etc.)
const usuario = $json && $json.id ? $json : {};
const original = $('Parsear Mensaje y Detectar Intención').first().json;

return [{
  json: {
    ...original,
    usuario
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;
const nombre = $json.contact_name || 'Cliente';
const registrado = !!$json.usuario?.id;

return [{
  json: {
    conversation_id: conversationId,
    content: `Hola **${nombre}!** 👋\n\nSoy *IAGRO*, tu asistente experto en clima para el campo 🌾\n\n🌦️ Pronósticos · 🚨 Alertas · 🌧️ Registro de lluvias · 🛰️ Imágenes satelitales · 🧑‍🌾 Consejos de fumigación y riego\n\n¿Qué necesitas hoy?`,
    content_type: 'input_select',
    content_attributes: {
      items: registrado
        ? [
            { title: '🌦️ Ver pronóstico', value: 'pronostico' },
            { title: '🚨 Alertas', value: 'alertas' },
            { title: '📋 Ver menú', value: 'menu' }
          ]
        : [
            { title: '🌦️ Ver pronóstico', value: 'pronostico' },
            { title: '🌧️ Ver radar', value: 'radar' },
            { title: '📋 Ver menú', value: 'menu' }
          ]
    }
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;
const MENU = [
  { title: '🌦️ Ver pronóstico', value: 'pronostico' },
  { title: '🌧️ Ver radar', value: 'radar' },
  { title: '🚨 Alertas', value: 'alertas' },
  { title: '🌧️ Registrar lluvia', value: 'registrar lluvia' },
  { title: '📊 Mis lluvias', value: 'mis lluvias' },
  { title: '💨 ¿Puedo fumigar?', value: 'fumigar' },
  { title: '💧 ¿Cuánto regar?', value: 'riego' },
  { title: '🛰️ Satélite', value: 'satelite' },
  { title: '⭐ Planes', value: 'planes' }
];

return [{
  json: {
    conversation_id: conversationId,
    content: '🌱 *IAGRO - Menú*\n\nEscribe o toca una opción:\n\n🌦️ *Pronóstico* — clima de los próximos días\n🌧️ *Radar* — lluvia en tiempo real\n🚨 *Alertas* — heladas, tormentas, viento, calor\n🌧️ *Registrar lluvia* — escribe: _llovió 15 mm_\n📊 *Mis lluvias* — tu historial y acumulados\n💨 *Fumigar* — mejores horarios para aplicar\n💧 *Riego* — cuánta agua necesita tu cultivo\n🛰️ *Satélite* — parcela, nubes y NDVI\n⭐ *Planes* — funciones Premium\n\n¡Estamos para ayudarte! 🌾',
    content_type: 'input_select',
    content_attributes: { items: MENU }
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;

return [{
  json: {
    conversation_id: conversationId,
    content: '👋 Gracias por usar *IAGRO*.\n\nSi necesitas un nuevo pronóstico o información climática, solo escribe:\n\n🌦️ *Pronóstico*\n🌧️ *Radar*\n📋 *Ayuda*\n\n¡Que tengas un excelente día! 🌾'
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;

return [{
  json: {
    conversation_id: conversationId,
    content: '🤔 No entendí tu mensaje.\n\nPuedes preguntarme cosas como:\n• _¿Va a llover?_\n• _Llovió 20 mm ayer_\n• _¿Puedo fumigar?_\n• _¿Hay alertas?_\n\nO escribe *Menú* para ver todas las opciones.',
    content_type: 'input_select',
    content_attributes: {
      items: [
        { title: '🌦️ Ver pronóstico', value: 'pronostico' },
        { title: '🚨 Alertas', value: 'alertas' },
        { title: '📋 Ver menú', value: 'menu' }
      ]
    }
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;

return [{
  json: {
    conversation_id: conversationId,
    content: '⚠️ Aún no tienes una cuenta registrada en **IAGRO**.\n\n👉 Por favor, ingresa al siguiente enlace y completa tu registro:\n\nhttps://iagro360.xyz/register.html\n\nUna vez registrado, podrás acceder a los servicios de *IAGRO*. 🌱'
  }
}];

const data = $json.data || [];
const usuario = $('Buscar Usuario por Teléfono').first().json;
const conversationId = $('Webhook').item.json.body.conversation.id;

// ===== Ajustes =====
const MM_MINIMO = 1;        // menos de esto en el día NO se considera lluvia (para "Próxima lluvia")
const VIENTO_FUMIGAR = 20;  // km/h: desde aquí no se recomienda fumigar
const DIAS_LISTA = 8;       // cuántos días van en "Próximos días"

// ===== Funciones auxiliares =====
const num = (v) => parseFloat(v);

const avgWind = (horarios) => {
  const vals = horarios.map(h => num(h.vsd)).filter(v => !isNaN(v));
  return vals.length ? Math.round(vals.reduce((a, b) => a + b, 0) / vals.length) : 0;
};

const avgWindDir = (horarios) => {
  const dirs = horarios.map(h => h.vdId).filter(Boolean);
  if (!dirs.length) return '';
  const freq = {};
  dirs.forEach(d => freq[d] = (freq[d] || 0) + 1);
  return Object.entries(freq).sort((a, b) => b[1] - a[1])[0][0];
};

const temps = (horarios) => horarios.map(h => num(h.td)).filter(v => !isNaN(v));
const maxTemp = (horarios) => { const t = temps(horarios); return t.length ? Math.round(Math.max(...t)) : '-'; };
const minTemp = (horarios) => { const t = temps(horarios); return t.length ? Math.round(Math.min(...t)) : '-'; };

const totalMm = (horarios) => horarios.reduce((s, h) => s + (num(h.sr) || 0), 0);

// Formato de mm: entero si es grande, 1 decimal si es poco
const fmtMm = (mm) => mm >= 1 ? String(Math.round(mm)) : (Math.round(mm * 10) / 10).toFixed(1);

const parseFecha = (fecha) => {
  const [dia, mes, anio] = fecha.split('/');
  return new Date(anio, mes - 1, dia, 12); // evita errores de zona horaria
};
const nombreLargo = (f) => ['domingo','lunes','martes','miércoles','jueves','viernes','sábado'][parseFecha(f).getDay()];
const nombreCorto = (f) => ['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'][parseFecha(f).getDay()];
const ddmm = (f) => f.slice(0, 5); // "06/10/2026" -> "06/10"

// ===== Procesar días (hoy + DIAS_LISTA días siguientes) =====
const dias = data.slice(0, 1 + DIAS_LISTA).map(dia => {
  const horarios = dia.horarios || [];
  const mm = totalMm(horarios);
  const horasLluvia = horarios.filter(h => num(h.sr) > 0);
  // Hora de inicio: primera hora con lluvia
  const primera = horasLluvia[0];
  // Probabilidad: la máxima de las horas con lluvia
  const prob = horasLluvia.length ? Math.max(...horasLluvia.map(h => num(h.rp) || 0)) : 0;
  return {
    fecha: dia.fecha,
    minT: minTemp(horarios),
    maxT: maxTemp(horarios),
    viento: avgWind(horarios),
    dir: avgWindDir(horarios),
    mm,
    llueve: mm >= MM_MINIMO,
    lluviaLigera: mm > 0 && mm < MM_MINIMO,
    horaInicio: primera ? primera.h : null,
    prob,
  };
});

// ===== Armar mensaje =====
let mensaje = `🌦️ **${usuario.nombre_propiedad}**\n`;

if (dias.length) {
  const hoy = dias[0];

  // HOY
  mensaje += `\n📍 *Hoy ${nombreLargo(hoy.fecha)} ${ddmm(hoy.fecha)}*\n`;
  mensaje += `🌡️ ${hoy.minT}° / ${hoy.maxT}°C  ·  💨 ${hoy.viento} km/h ${hoy.dir}\n`;

  // PRÓXIMA LLUVIA (depende del umbral MM_MINIMO)
  const proxima = dias.find(d => d.llueve);
  if (proxima) {
    const cuando = proxima === hoy
      ? 'hoy'
      : `${nombreLargo(proxima.fecha)} ${ddmm(proxima.fecha)}`;
    mensaje += `\n🌧️ *Próxima lluvia:* ${cuando} desde las ${proxima.horaInicio}\n`;
    mensaje += `Se esperan unos ${Math.round(proxima.mm)} mm (probabilidad ${proxima.prob}%)\n`;
  } else {
    mensaje += `\n☀️ *Sin lluvias importantes en los próximos días*\n`;
  }

  // PRÓXIMOS DÍAS (una línea por día)
  mensaje += `\n📅 *Próximos días*\n`;
  for (const d of dias.slice(1, 1 + DIAS_LISTA)) {
    let icono, extra;
    if (d.llueve) {
      icono = '🌧️';
      extra = `💧 ${fmtMm(d.mm)} mm`;
    } else if (d.lluviaLigera) {
      icono = '🌦️';
      extra = `💧 ${fmtMm(d.mm)} mm`;
    } else {
      icono = '☀️';
      extra = `💨 ${d.viento}`;
    }
    mensaje += `${nombreCorto(d.fecha)} ${ddmm(d.fecha)} ${icono} ${d.minT}°–${d.maxT}° ${extra}\n`;
  }

  // RECOMENDACIÓN
  const proximos3 = dias.slice(0, 3);
  const ventosos = proximos3.filter(d => d.viento >= VIENTO_FUMIGAR).length;
  const calorExtremo = proximos3.some(d => d.maxT !== '-' && d.maxT > 35);
  const frio = proximos3.some(d => d.minT !== '-' && d.minT < 16);

  const avisos = [];
  if (proxima && proxima !== hoy) {
    const diasSecos = dias.indexOf(proxima);
    if (diasSecos >= 2) avisos.push(`${diasSecos} días secos antes de la lluvia`);
  }
  if (ventosos >= 2) avisos.push('⚠️ viento fuerte, no recomendable fumigar');
  else if (!proxima || proxima !== hoy) avisos.push('✅ buen momento para aplicaciones en días de poco viento');
  if (calorExtremo) avisos.push('🌡️ calor extremo');
  if (frio) avisos.push('🥶 temperaturas frías');

  if (avisos.length) mensaje += `\n💡 *Resumen:* ${avisos.join(' · ')}\n`;
}

mensaje += `\n🌐 Radar en vivo: https://iagro360.xyz/radar/${usuario.id}\n`;
mensaje += `\n📡 _IAGRO | Monitoreo Climático Inteligente_`;

return [{
  json: {
    conversation_id: conversationId,
    content: mensaje,
    content_type: 'input_select',
    content_attributes: {
      items: [
        { title: '🌦️ Ver pronóstico', value: 'pronostico' },
        { title: '🌧️ Ver radar', value: 'radar' }
      ]
    }
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;

return [{
  json: {
    conversation_id: conversationId,
    content: '⚠️ No pudimos obtener el pronóstico en este momento. Por favor, intenta nuevamente en unos minutos. 🙏'
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;

return [{
  json: {
    conversation_id: conversationId,
    content: '❌ *IAGRO*\n\nNo pudimos validar tu código de registro. Verifica que el mensaje no haya sido modificado e intenta nuevamente, o contacta a soporte.'
  }
}];

return [{
  json: {
    ...$json,
    telefono: $('Parsear Mensaje y Detectar Intención').first().json.telefono
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;

return [{
  json: {
    conversation_id: conversationId,
    content: '🌱 *IAGRO*\n\n⚠️ Este número ya tiene una cuenta registrada.\n\nSi crees que esto es un error, contacta a soporte.'
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;

return [{
  json: {
    conversation_id: conversationId,
    content: '🌱 *IAGRO*\n\n✅ *¡Registro exitoso!*\n\n¿Qué deseas hacer ahora?',
    content_type: 'input_select',
    content_attributes: {
      items: [
        { title: '🌦️ Ver pronóstico', value: 'pronostico' },
        { title: '🌧️ Ver radar', value: 'radar' },
        { title: '⚙️ Configuración', value: 'configuracion' }
      ]
    }
  }
}];

const payload = {
  content: $json.content,
  message_type: 'outgoing',
  private: false
};

if ($json.content_type) payload.content_type = $json.content_type;
if ($json.content_attributes) payload.content_attributes = $json.content_attributes;

return [{
  json: {
    conversation_id: $json.conversation_id,
    chatwoot_payload: payload
  }
}];

const usuario = $('Buscar Usuario por Teléfono').first().json;
const conversationId = $('Webhook').item.json.body.conversation.id;

const mensaje = `🌧️ *Radar de lluvias en tiempo real*

📍 Consulta la actividad de lluvias en tu zona desde el radar:

👉 https://iagro360.xyz/radar/${usuario.id}

📡 _IAGRO | Monitoreo Climático Inteligente_`;

return [{
  json: {
    conversation_id: conversationId,
    content: mensaje,
    content_type: 'input_select',
    content_attributes: {
      items: [
        { title: '🌦️ Ver pronóstico', value: 'pronostico' },
        { title: '🌧️ Ver radar', value: 'radar' }
      ]
    }
  }
}];

// Viene de "Guardar Lluvia" (INSERT + totales en una sola consulta)
const r = $json;
const ctx = $('Adjuntar Datos de Usuario').first().json;
const conversationId = $('Webhook').item.json.body.conversation.id;

const num = (v) => Number(v || 0);
const fmt = (v) => num(v).toLocaleString('es', { maximumFractionDigits: 1 });
const mm = num(ctx.lluvia.mm);
const f = DateTime.fromISO(ctx.lluvia.fecha).setLocale('es');
const fecha = f.toFormat("cccc d 'de' LLLL");
const mes = f.toFormat('LLLL');

let consejo;
if (mm >= 40) consejo = '⛈️ Fue un aguacero fuerte. Revisa encharcamientos y erosión; espera a que el suelo drene antes de entrar con maquinaria.';
else if (mm >= 15) consejo = '💚 Muy buena lluvia. El suelo debería tener humedad para varios días: puedes suspender el riego.';
else if (mm >= 5) consejo = '🌱 Lluvia moderada. Ayuda, pero quizá necesites riego complementario pronto.';
else consejo = '💧 Lluvia ligera: moja la superficie pero casi no llega a las raíces.';

const mensaje = `✅ *Lluvia registrada*\n\n📅 ${fecha}\n📍 ${ctx.lluvia.lote}\n🌧️ *${fmt(mm)} mm* ≈ ${(mm * 10000).toLocaleString('es')} litros por hectárea\n\n📊 *Acumulados*\n• Mes de ${mes}: *${fmt(r.total_mes)} mm*\n• Año ${f.year}: *${fmt(r.total_anio)} mm*\n• Registros: ${r.registros}\n\n🤖 ${consejo}`;

return [{
  json: {
    conversation_id: conversationId,
    content: mensaje,
    content_type: 'input_select',
    content_attributes: {
      items: [
        { title: '📊 Mis lluvias', value: 'mis lluvias' },
        { title: '💧 ¿Cuánto regar?', value: 'riego' },
        { title: '📋 Ver menú', value: 'menu' }
      ]
    }
  }
}];

// Viene de "Consultar Historial Lluvias" (una fila con agregados)
const r = $json;
const conversationId = $('Webhook').item.json.body.conversation.id;
const num = (v) => Number(v || 0);
const fmt = (v) => num(v).toLocaleString('es', { maximumFractionDigits: 1 });

if (!num(r.registros)) {
  return [{
    json: {
      conversation_id: conversationId,
      content: '📒 Aún no tienes lluvias registradas.\n\nCada vez que llueva escríbeme, por ejemplo: _llovió 12 mm_ o _llovió 8 mm ayer en el lote norte_, y yo llevo tu cuaderno de campo con los acumulados del mes y del año.'
    }
  }];
}

const parse = (v) => (typeof v === 'string' ? JSON.parse(v) : v) || [];
const ultimos = parse(r.ultimos);
const meses = parse(r.meses);

// Últimos 6 meses (incluye meses sin lluvia) con barras de texto
const nombres = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
const filas = [];
for (let i = 5; i >= 0; i--) {
  const d = $now.minus({ months: i });
  const key = d.toFormat('yyyy-LL');
  const total = num((meses.find(m => m.mes === key) || {}).total);
  filas.push({ label: nombres[d.month - 1], total });
}
const max = Math.max(1, ...filas.map(f => f.total));
const barras = filas
  .map(f => `${f.label} ${'▇'.repeat(Math.round((f.total / max) * 10)) || '▁'} ${fmt(f.total)}`)
  .join('\n');

const lista = ultimos
  .map(u => `• ${DateTime.fromISO(String(u.fecha).slice(0, 10)).toFormat('dd/LL')} — *${fmt(u.mm)} mm* (${u.lote})`)
  .join('\n');

const mensaje = `📊 *Tu cuaderno de lluvias*\n\n🗓️ Este mes: *${fmt(r.total_mes)} mm*\n📆 Este año: *${fmt(r.total_anio)} mm*\n⏱️ Últimos 30 días: *${fmt(r.total_30d)} mm*\n🧾 Registros: ${r.registros}\n\n📈 *Últimos 6 meses (mm)*\n${barras}\n\n🕐 *Últimos registros*\n${lista}`;

return [{
  json: {
    conversation_id: conversationId,
    content: mensaje,
    content_type: 'input_select',
    content_attributes: {
      items: [
        { title: '🌧️ Registrar lluvia', value: 'registrar lluvia' },
        { title: '💧 ¿Cuánto regar?', value: 'riego' },
        { title: '📋 Ver menú', value: 'menu' }
      ]
    }
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;

return [{
  json: {
    conversation_id: conversationId,
    content: '⚠️ No pudimos acceder a tu registro de lluvias en este momento. Por favor, intenta nuevamente en unos minutos. 🙏'
  }
}];

// Analiza datos de Open-Meteo para: alertas | fumigar | riego
const d = $json.daily || {};
const h = $json.hourly || {};
const ctx = $('Adjuntar Datos de Usuario').first().json;
const usuario = ctx.usuario || {};
const intent = ctx.intent;
const conversationId = $('Webhook').item.json.body.conversation.id;

// ===== Umbrales (ajustables) =====
const HELADA = 2;          // °C mínima
const LLUVIA_FUERTE = 20;  // mm/día
const RAFAGA = 50;         // km/h
const CALOR = 34;          // °C máxima
const UV_EXTREMO = 11;
const KC = 1.0;            // coeficiente de cultivo genérico (maíz 1.15, papa 1.1, café 0.95...)

const r = (v) => Math.round(Number(v) || 0);
const fmt = (v) => (Number(v) || 0).toLocaleString('es', { maximumFractionDigits: 1 });
const DIAS = ['Dom', 'Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb'];
const nombreDia = (iso, i) => i === 0 ? 'Hoy' : i === 1 ? 'Mañana' : `${DIAS[new Date(iso + 'T12:00').getDay()]} ${iso.slice(8, 10)}/${iso.slice(5, 7)}`;
const finca = usuario.nombre_propiedad || 'tu campo';

// Hora local actual de la ubicación (Open-Meteo devuelve utc_offset_seconds)
const ahoraLocal = new Date(Date.now() + ($json.utc_offset_seconds || 0) * 1000).toISOString().slice(0, 13) + ':00';
let i0 = (h.time || []).indexOf(ahoraLocal);
if (i0 < 0) i0 = 0;

let mensaje = '';
let botones = [];

// =====================================================
// ALERTAS (7 días)
// =====================================================
if (intent === 'alertas') {
  const alertas = [];
  (d.time || []).forEach((fecha, i) => {
    const dia = nombreDia(fecha, i);
    const tmin = d.temperature_2m_min[i], tmax = d.temperature_2m_max[i];
    const lluvia = d.precipitation_sum[i], rafaga = d.wind_gusts_10m_max[i];
    const code = d.weather_code[i], uv = d.uv_index_max[i];
    if (tmin <= HELADA) alertas.push(`${tmin <= 0 ? '🔴' : '🟠'} 🥶 *Helada — ${dia}*: mínima ${fmt(tmin)} °C. Riega la tarde anterior, cubre almácigos y evita podas.`);
    if (lluvia >= LLUVIA_FUERTE) alertas.push(`${lluvia >= 50 ? '🔴' : '🟠'} 🌧️ *Lluvia intensa — ${dia}*: ${fmt(lluvia)} mm. Limpia canales y posterga fertilización y fumigación.`);
    if ([95, 96, 99].includes(code)) alertas.push(`🔴 ⛈️ *${code >= 96 ? 'Tormenta con granizo' : 'Tormenta eléctrica'} — ${dia}*. Evita trabajar en campo abierto.`);
    if (rafaga >= RAFAGA) alertas.push(`${rafaga >= 75 ? '🔴' : '🟡'} 💨 *Viento fuerte — ${dia}*: ráfagas de ${r(rafaga)} km/h. Asegura invernaderos y tutores.`);
    if (tmax >= CALOR) alertas.push(`${tmax >= 38 ? '🔴' : '🟠'} 🔥 *Calor extremo — ${dia}*: máxima ${fmt(tmax)} °C. Riega temprano y protege a trabajadores y animales.`);
    if (uv >= UV_EXTREMO) alertas.push(`🟡 ☀️ *UV extremo — ${dia}*: índice ${fmt(uv)}. Evita exposición al mediodía.`);
  });

  if (alertas.length) {
    mensaje = `🚨 *${alertas.length} alerta${alertas.length > 1 ? 's' : ''} para ${finca}* (7 días)\n\n${alertas.slice(0, 8).join('\n\n')}`;
  } else {
    mensaje = `✅ *Sin alertas climáticas para ${finca}*\n\nNo detecto heladas, lluvias intensas, tormentas, vientos fuertes ni calor extremo en los próximos 7 días. 🌾`;
  }
  mensaje += `\n\n🌡️ Mínima más baja: ${fmt(Math.min(...d.temperature_2m_min))} °C · Máxima más alta: ${fmt(Math.max(...d.temperature_2m_max))} °C`;
  botones = [
    { title: '💨 ¿Puedo fumigar?', value: 'fumigar' },
    { title: '🌦️ Ver pronóstico', value: 'pronostico' },
    { title: '📋 Ver menú', value: 'menu' }
  ];
}

// =====================================================
// VENTANAS DE FUMIGACIÓN (48 h)
// =====================================================
if (intent === 'fumigar') {
  const apta = (i) => {
    const hr = Number(h.time[i].slice(11, 13));
    const ws = h.wind_speed_10m[i], pp = h.precipitation_probability[i] ?? 0;
    const tt = h.temperature_2m[i], hr2 = h.relative_humidity_2m[i];
    const lluviaPronto = (h.precipitation_probability.slice(i, i + 4)).some(p => p >= 50);
    return hr >= 6 && hr <= 18 && ws >= 3 && ws < 15 && pp < 30 && tt >= 10 && tt <= 28 && hr2 >= 45 && !lluviaPronto;
  };

  const ventanas = [];
  let cur = null;
  for (let i = i0; i < Math.min(i0 + 48, h.time.length); i++) {
    if (apta(i)) { if (!cur) cur = { s: i, e: i }; else cur.e = i; }
    else if (cur) { ventanas.push(cur); cur = null; }
  }
  if (cur) ventanas.push(cur);
  const buenas = ventanas.filter(w => w.e - w.s >= 1).slice(0, 3);

  const etiqueta = (i) => {
    const off = Math.round((Date.parse(h.time[i].slice(0, 10)) - Date.parse(h.time[i0].slice(0, 10))) / 864e5);
    return `${off === 0 ? 'Hoy' : off === 1 ? 'Mañana' : 'Pasado mañana'} ${h.time[i].slice(11, 16)}`;
  };

  const ahora = apta(i0)
    ? `✅ *Ahora puedes aplicar*\nViento ${r(h.wind_speed_10m[i0])} km/h · Humedad ${r(h.relative_humidity_2m[i0])}% · ${r(h.temperature_2m[i0])} °C`
    : `⛔ *Ahora no es recomendable*\nViento ${r(h.wind_speed_10m[i0])} km/h · Lluvia ${r(h.precipitation_probability[i0])}% · ${r(h.temperature_2m[i0])} °C · HR ${r(h.relative_humidity_2m[i0])}%`;

  const lista = buenas.length
    ? buenas.map(w => `🟢 ${etiqueta(w.s)} → ${h.time[w.e].slice(11, 16)} (${w.e - w.s + 1} h)`).join('\n')
    : '😕 No encontré ventanas seguras en las próximas 48 h.';

  mensaje = `💨 *Ventanas de fumigación — ${finca}*\n\n${ahora}\n\n📋 *Mejores horarios (48 h)*\n${lista}\n\n_Criterios: viento 3–15 km/h, sin lluvia en las 4 h siguientes, 10–28 °C y humedad ≥ 45 % para reducir deriva y evaporación._`;
  botones = [
    { title: '🚨 Alertas', value: 'alertas' },
    { title: '💧 ¿Cuánto regar?', value: 'riego' },
    { title: '📋 Ver menú', value: 'menu' }
  ];
}

// =====================================================
// RIEGO: balance hídrico 7 días (ET0 FAO-56)
// =====================================================
if (intent === 'riego') {
  const et0 = (d.et0_fao_evapotranspiration || []).reduce((a, b) => a + (b || 0), 0);
  const etc = et0 * KC;
  const lluviaEfectiva = (d.precipitation_sum || []).reduce((a, b) => a + (b || 0), 0) * 0.8;
  const deficit = Math.max(0, etc - lluviaEfectiva);
  const m3ha = deficit * 10; // 1 mm = 10 m³/ha

  const recomendacion = deficit < 3
    ? '🎉 No necesitas regar esta semana: la lluvia prevista cubre la demanda del cultivo.'
    : `Aplica unos *${fmt(deficit)} mm* en la semana ≈ *${fmt(m3ha)} m³ por hectárea*. Divide en 2–3 riegos, de preferencia temprano en la mañana.`;

  mensaje = `💧 *Balance hídrico — ${finca}* (7 días)\n\n🌡️ Evapotranspiración del cultivo: ${fmt(etc)} mm\n🌧️ Lluvia efectiva prevista: ${fmt(lluviaEfectiva)} mm\n➖ *Déficit: ${fmt(deficit)} mm*\n\n🤖 ${recomendacion}\n\n_Cálculo FAO-56 con coeficiente de cultivo genérico (Kc ${KC})._`;
  botones = [
    { title: '🌧️ Registrar lluvia', value: 'registrar lluvia' },
    { title: '🌦️ Ver pronóstico', value: 'pronostico' },
    { title: '📋 Ver menú', value: 'menu' }
  ];
}

const content = mensaje + `\n\n📡 _IAGRO | Monitoreo Climático Inteligente_`;

// WhatsApp rechaza mensajes con botones si el texto supera 1024 caracteres
if (content.length > 1000) {
  return [{ json: { conversation_id: conversationId, content } }];
}

return [{
  json: {
    conversation_id: conversationId,
    content,
    content_type: 'input_select',
    content_attributes: { items: botones }
  }
}];

// Construye la URL de la imagen satelital según lo que pidió el usuario
const ctx = $json;
const u = ctx.usuario || {};
const lat = Number(u.latitude), lon = Number(u.longitude);
const tipo = ctx.satelite_tipo || 'parcela';
const conversationId = $('Webhook').item.json.body.conversation.id;
const finca = u.nombre_propiedad || 'tu campo';
const ayer = $now.minus({ days: 1 }).toISODate();

// Recuadro alrededor del punto (grados)
const bbox = (dLat, dLon) => ({ s: lat - dLat, n: lat + dLat, w: lon - dLon, e: lon + dLon });
const gibs = (capa, b, formato, fecha) =>
  'https://gibs.earthdata.nasa.gov/wms/epsg4326/best/wms.cgi?SERVICE=WMS&REQUEST=GetMap&VERSION=1.3.0' +
  `&LAYERS=${capa}&STYLES=&CRS=EPSG:4326&BBOX=${b.s},${b.w},${b.n},${b.e}&WIDTH=800&HEIGHT=800&FORMAT=${formato}` +
  (fecha ? `&TIME=${fecha}` : '');

let image_url, filename, caption;

if (tipo === 'nubes') {
  image_url = gibs('MODIS_Terra_CorrectedReflectance_TrueColor', bbox(2.5, 2.5), 'image/jpeg', ayer);
  filename = `nubes_${ayer}.jpg`;
  caption = `☁️ *Nubosidad sobre tu región* — satélite MODIS (NASA), ${DateTime.fromISO(ayer).toFormat('dd/LL/yyyy')}\n\n📍 ${finca} está en el *centro* de la imagen (≈ 550 km de lado). Las zonas blancas son nubes y sistemas de lluvia.`;
} else if (tipo === 'ndvi') {
  image_url = gibs('MODIS_Terra_NDVI_8Day', bbox(0.25, 0.25), 'image/png');
  filename = 'ndvi.png';
  caption = `🌱 *NDVI — salud de la vegetación* (MODIS NASA, compuesto de 8 días)\n\n📍 ${finca} está en el *centro* (≈ 55 km de lado).\n🟩 Verde intenso = vegetación vigorosa\n🟨 Verde claro = vigor medio\n🟫 Marrón = suelo desnudo o vegetación estresada\n\n_Resolución 250 m: ideal para ver tendencias de la zona._`;
} else {
  const b = bbox(0.004, 0.006);
  image_url = 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/export' +
    `?bbox=${b.w},${b.s},${b.e},${b.n}&bboxSR=4326&imageSR=3857&size=800,600&format=jpg&f=image`;
  filename = 'parcela.jpg';
  caption = `🛰️ *Vista satelital de ${finca}*\n\n📍 Tu campo está en el *centro* de la imagen (≈ 1,3 km de lado).\n📌 Coordenadas: ${lat.toFixed(5)}, ${lon.toFixed(5)}\n\n_Imagen de alta resolución (Esri World Imagery); puede tener algunos meses de antigüedad._`;
}

return [{
  json: { conversation_id: conversationId, image_url, filename, caption, tipo }
}];

// Pone nombre y extensión correctos al archivo descargado (las URLs de WMS terminan en "wms.cgi")
const item = $input.first();
const prep = $('Preparar Imagen Satelital').first().json;
if (item.binary && item.binary.data) {
  item.binary.data.fileName = prep.filename;
  item.binary.data.fileExtension = prep.filename.split('.').pop();
  item.binary.data.mimeType = prep.filename.endsWith('.png') ? 'image/png' : 'image/jpeg';
}
return [item];

// Después de enviar la imagen, ofrece las otras capas
const prep = $('Preparar Imagen Satelital').first().json;
const opciones = [
  { title: '🛰️ Mi parcela', value: 'satelite parcela', tipo: 'parcela' },
  { title: '☁️ Nubes hoy', value: 'satelite nubes', tipo: 'nubes' },
  { title: '🌱 NDVI', value: 'satelite ndvi', tipo: 'ndvi' }
].filter(o => o.tipo !== prep.tipo).map(({ title, value }) => ({ title, value }));

return [{
  json: {
    conversation_id: prep.conversation_id,
    content: '¿Quieres ver otra capa satelital? 🛰️',
    content_type: 'input_select',
    content_attributes: {
      items: [...opciones, { title: '📋 Ver menú', value: 'menu' }]
    }
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;

return [{
  json: {
    conversation_id: conversationId,
    content: '⚠️ No pudimos obtener la imagen satelital en este momento. Por favor, intenta nuevamente en unos minutos. 🙏'
  }
}];

const conversationId = $('Webhook').item.json.body.conversation.id;
const error = $json.lluvia_error ? `⚠️ ${$json.lluvia_error}

` : '';

return [{
  json: {
    conversation_id: conversationId,
    content: `${error}🌧️ *Registro de lluvia*

Escríbeme cuánto marcó tu pluviómetro, por ejemplo:

• _llovió 15 mm_
• _llovió 8,5 mm ayer_
• _cayeron 20 mm en el lote norte_
• _lluvia 12 mm 05/10_

Yo llevo tu cuaderno de campo y te muestro los acumulados del mes y del año 📒`
  }
}];
